using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AstriumSoulOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/AstriumSoulOmenData")]
public class AstriumSoulOmenData : PlayerAndSentinelsExceededPurifyOmenData
{
	[Header("AstriumSoulOmenData")]
	[SerializeField]
	private int purifyDivider = 2;

	protected override void ExceededPurifyAction(int exceededPurifyAmount, OmenInstance omenInstance)
	{
		omenInstance.EnqueueOmenFeedbackAndPlay();
		OmenLogic.ActivateOmen(null, Mathf.FloorToInt((float)exceededPurifyAmount / (float)purifyDivider), null, null);
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetPurifyReceiveThatExceedDescription(), base.localizationManager.GetLocalizedWhereX(GetOmenConvertedDescriptionBattleAction().RemoveLast(), y: false, Smart.Format(GetOmenRawLocalizedDescription(), purifyDivider, base.localizationManager.GetLocalizedRoundedDown())));
	}
}
